import{_ as t,a,c as o,ac as n}from"./chunks/framework.BSuaGltH.js";const b=JSON.parse('{"title":"第一册：英语初阶 · Lesson 75 Uncomfortable shoes","description":"学习 过去时间标记与 buy/bought，配有原创例句、重点词汇和带解析的自测。","frontmatter":{"title":"第一册：英语初阶 · Lesson 75 Uncomfortable shoes","description":"学习 过去时间标记与 buy/bought，配有原创例句、重点词汇和带解析的自测。","showdocs":{"topics":[{"id":"english","title":"英语","link":"/topics/english/"}],"kind":"路线与能力起点","scope":"general","audience":"general","group":"学习与记录","seriesTitle":"新概念英语经典版第1册课时","summary":"学习 过去时间标记与 buy/bought，配有原创例句、重点词汇和带解析的自测。","status":"active","related":[{"title":"程序员英语 08：一次完整的阅读与协作实战","link":"/life/english/programmer/practice","kind":"读写与对话练习","scope":"general","audience":"general"},{"title":"第二册：实践与进步 · 单元 1 单词与短语","link":"/life/english/new-concept/book-2/unit-01/vocabulary","kind":"句法与表达查阅","scope":"general","audience":"general"},{"title":"第二册：实践与进步 · 单元 1 单词与短语 · 第17–24课","link":"/life/english/new-concept/book-2/unit-01/vocabulary-part-02","kind":"句法与表达查阅","scope":"general","audience":"general"},{"title":"第二册：实践与进步 · 单元 1 单词与短语 · 字母索引与第1–16课","link":"/life/english/new-concept/book-2/unit-01/vocabulary-part-01","kind":"句法与表达查阅","scope":"general","audience":"general"},{"title":"第二册：实践与进步 · 单元 1 复习与自测","link":"/life/english/new-concept/book-2/unit-01/review","kind":"读写与对话练习","scope":"general","audience":"general"}],"prev":{"text":"第一册：英语初阶 · Lesson 74 What did they do?","link":"/life/english/new-concept/book-1/unit-04/lesson-074"},"next":{"text":"第一册：英语初阶 · Lesson 76 When did you ...?","link":"/life/english/new-concept/book-1/unit-04/lesson-076"}},"layout":"ReadingPage","sidebar":false,"aside":false,"prev":{"text":"第一册：英语初阶 · Lesson 74 What did they do?","link":"/life/english/new-concept/book-1/unit-04/lesson-074"},"next":{"text":"第一册：英语初阶 · Lesson 76 When did you ...?","link":"/life/english/new-concept/book-1/unit-04/lesson-076"}},"headers":[],"relativePath":"life/english/new-concept/book-1/unit-04/lesson-075.md","filePath":"life/english/new-concept/book-1/unit-04/lesson-075.md"}'),s={name:"life/english/new-concept/book-1/unit-04/lesson-075.md"};function i(l,e,r,h,d,u){return a(),o("div",null,[...e[0]||(e[0]=[n('<h1 id="第一册-英语初阶-·-lesson-75-uncomfortable-shoes" tabindex="-1">第一册：英语初阶 · Lesson 75 Uncomfortable shoes <a class="header-anchor" href="#第一册-英语初阶-·-lesson-75-uncomfortable-shoes" aria-label="Permalink to &quot;第一册：英语初阶 · Lesson 75 Uncomfortable shoes&quot;">​</a></h1><p><a href="/life/english/new-concept/overview">系列目录</a> · <a href="/life/english/new-concept/book-1/contents">本册目录</a> · <a href="/life/english/new-concept/book-1/unit-04/overview">单元 4</a> · <a href="/life/english/new-concept/book-1/unit-04/lesson-076">配套课 Lesson 76</a></p><h2 id="学习目标与内容导读" tabindex="-1">学习目标与内容导读 <a class="header-anchor" href="#学习目标与内容导读" aria-label="Permalink to &quot;学习目标与内容导读&quot;">​</a></h2><p>比较过去购买与现在需要 本课要掌握过去时间标记与 buy/bought，能够理解人物、对象及说话目的，并把相同结构用于自己的生活。先根据情境判断为什么要这样问或这样说，再看语言形式。</p><p>本课为情景学习；完成后进入相邻偶数课进行句型迁移。</p><h2 id="单词与搭配" tabindex="-1">单词与搭配 <a class="header-anchor" href="#单词与搭配" aria-label="Permalink to &quot;单词与搭配&quot;">​</a></h2><table tabindex="0"><thead><tr><th>单词</th><th>音标</th><th>词性</th><th>本页义项</th><th>搭配</th></tr></thead><tbody><tr><td>uncomfortable</td><td>/ʌnˈkʌmftəbl/</td><td>adj.</td><td>不舒适的</td><td>uncomfortable shoes</td></tr><tr><td>size</td><td>/saɪz/</td><td>n.</td><td>尺码</td><td>the right size</td></tr><tr><td>pair</td><td>/peə/</td><td>n.</td><td>一双；一对</td><td>a pair of shoes</td></tr><tr><td>ago</td><td>/əˈɡəʊ/</td><td>adv.</td><td>以前</td><td>two weeks ago</td></tr></tbody></table><h2 id="短语与句型" tabindex="-1">短语与句型 <a class="header-anchor" href="#短语与句型" aria-label="Permalink to &quot;短语与句型&quot;">​</a></h2><ul><li>a pair of — 一双，pair 可计数</li><li>two days ago — 两天以前</li></ul><h2 id="语法讲解-过去时间标记与-buy-bought" tabindex="-1">语法讲解：过去时间标记与 buy/bought <a class="header-anchor" href="#语法讲解-过去时间标记与-buy-bought" aria-label="Permalink to &quot;语法讲解：过去时间标记与 buy/bought&quot;">​</a></h2><p>明确结束的过去时间如 last month、two days ago，通常与一般过去时配合。buy 的过去式为 bought，wear 的过去式为 wore。ago 表从现在向前推多少时间，放在数量短语之后。询问过去购买用 Did you buy ...?，不能在 did 后保留 bought。大小合适与舒适是不同属性，描述时可分别说明。</p><h2 id="原创例句与结构分析" tabindex="-1">原创例句与结构分析 <a class="header-anchor" href="#原创例句与结构分析" aria-label="Permalink to &quot;原创例句与结构分析&quot;">​</a></h2><blockquote><p>I bought these boots three weeks ago.</p></blockquote><p>我三周前买了这双靴子。</p><p>Bought 是 buy 的不规则过去式；these boots 为宾语，three weeks ago 表从现在回溯三周。</p><h2 id="易错辨析" tabindex="-1">易错辨析 <a class="header-anchor" href="#易错辨析" aria-label="Permalink to &quot;易错辨析&quot;">​</a></h2><p>two weeks ago 前一般不加 in；ago 放在时间长度之后。</p><h2 id="听说训练" tabindex="-1">听说训练 <a class="header-anchor" href="#听说训练" aria-label="Permalink to &quot;听说训练&quot;">​</a></h2><p>请同伴朗读本课原创示范，或先自行录音，再遮住文字听写“I bought these boots three weeks ago.”。核对词序与漏词后，用下方句子分析说明每个词组的作用。随后不看原句说出中文意思，再换一个对象重新说一句。没有录音时，可用同伴朗读和问答完成同样的训练。</p><h2 id="读写训练" tabindex="-1">读写训练 <a class="header-anchor" href="#读写训练" aria-label="Permalink to &quot;读写训练&quot;">​</a></h2><h3 id="阅读材料-本站原创" tabindex="-1">阅读材料（本站原创） <a class="header-anchor" href="#阅读材料-本站原创" aria-label="Permalink to &quot;阅读材料（本站原创）&quot;">​</a></h3><p>I bought these boots three weeks ago. Did you wear the new shoes yesterday?</p><h3 id="表达任务" tabindex="-1">表达任务 <a class="header-anchor" href="#表达任务" aria-label="Permalink to &quot;表达任务&quot;">​</a></h3><p>围绕“比较过去购买与现在需要”写两至三句，再读给同伴听。至少使用一次过去时间标记与 buy/bought，改变一个人物或对象后再说一遍。</p><details class="details custom-block"><summary>写作提示与点评</summary><p>Bought 是 buy 的不规则过去式；these boots 为宾语，three weeks ago 表从现在回溯三周。 Did 承担过去标记，wear 不用过去式 wore；the new shoes 为宾语，yesterday 指过去一天。</p></details><h2 id="课后自测" tabindex="-1">课后自测 <a class="header-anchor" href="#课后自测" aria-label="Permalink to &quot;课后自测&quot;">​</a></h2><h3 id="练习-1" tabindex="-1">练习 1 <a class="header-anchor" href="#练习-1" aria-label="Permalink to &quot;练习 1&quot;">​</a></h3><p>填过去式：I ___ (buy) these boots last month.</p><details class="details custom-block"><summary>参考答案与解析</summary><p><strong>答案：</strong> bought</p><p><strong>解析：</strong> 按本课规则判断：明确结束的过去时间如 last month、two days ago，通常与一般过去时配合。buy 的过去式为 bought，wear 的过去式为 wore。ago 表从现在向前推多少时间，放在数量短语之后。询问过去购买用 Did you buy ...?，不能在 did 后保留 bought。大小合适与舒适是不同属性，描述时可分别说明。</p></details><h3 id="练习-2" tabindex="-1">练习 2 <a class="header-anchor" href="#练习-2" aria-label="Permalink to &quot;练习 2&quot;">​</a></h3><p>把“我三周前买了这双靴子。”译成英语，保留人物、动作与时间信息。</p><details class="details custom-block"><summary>参考答案与解析</summary><p><strong>答案：</strong> I bought these boots three weeks ago.</p><p><strong>解析：</strong> Bought 是 buy 的不规则过去式；these boots 为宾语，three weeks ago 表从现在回溯三周。</p></details><h3 id="练习-3" tabindex="-1">练习 3 <a class="header-anchor" href="#练习-3" aria-label="Permalink to &quot;练习 3&quot;">​</a></h3><p>说明下面句子表达的信息，并译成中文：Did you wear the new shoes yesterday?</p><details class="details custom-block"><summary>参考答案与解析</summary><p><strong>答案：</strong> 你昨天穿了新鞋吗？</p><p><strong>解析：</strong> Did 承担过去标记，wear 不用过去式 wore；the new shoes 为宾语，yesterday 指过去一天。</p></details><h2 id="复习导航" tabindex="-1">复习导航 <a class="header-anchor" href="#复习导航" aria-label="Permalink to &quot;复习导航&quot;">​</a></h2><p>本课重点：过去时间标记与 buy/bought。复习时先遮住答案重做自测，再将示范中的人物、时间或条件改为自己的情境；解释改动后哪些词需要变化。</p><p><a href="/life/english/new-concept/book-1/unit-04/grammar">单元语法</a> · <a href="/life/english/new-concept/book-1/unit-04/vocabulary">单元单词</a> · <a href="/life/english/new-concept/book-1/unit-04/review">单元自测</a></p><p><a href="/life/english/new-concept/book-1/unit-04/lesson-074">上一课</a> · <a href="/life/english/new-concept/book-1/unit-04/overview">单元目录</a> · <a href="/life/english/new-concept/book-1/unit-04/lesson-076">下一课</a></p><hr><p>本站原创学习伴读：保留经典版课号和课名，讲解、例句与练习独立编写。重点词汇用于本页学习，不等同于教材全部生词表；教材课文、完整译文、原题与录音请配合自己的正版教材使用。</p>',41)])])}const p=t(s,[["render",i]]);export{b as __pageData,p as default};
